function usablePrefix(indexColumns, predicates) {
  let used = 0;
  for (let i = 0; i < indexColumns.length; i += 1) {
    const column = indexColumns[i];
    let op = null;
    for (let j = 0; j < predicates.length; j += 1) {
      if (predicates[j].column === column) {
        op = predicates[j].op;
        break;
      }
    }
    if (op === 'eq') {
      used += 1;
    } else if (op === 'range') {
      used += 1;
      break;
    } else {
      break;
    }
  }
  return used;
}

