function pageAfter(rows, cursor, size) {
  if (size <= 0) return { ids: [], nextCursor: null };
  const ids = [];
  let last = null;
  for (let i = 0; i < rows.length && ids.length < size; i += 1) {
    const row = rows[i];
    let after = true;
    if (cursor !== null && cursor !== undefined) {
      if (row.scheduledFor < cursor.scheduledFor) {
        after = false;
      } else if (row.scheduledFor === cursor.scheduledFor && row.id <= cursor.id) {
        after = false;
      }
    }
    if (after) {
      ids.push(row.id);
      last = row;
    }
  }
  const nextCursor = last === null
    ? null
    : { scheduledFor: last.scheduledFor, id: last.id };
  return { ids, nextCursor };
}

