function applyEdit(record, edit) {
  if (edit.expectedRevision !== record.revision) {
    return {
      status: 'conflict',
      serverRevision: record.revision,
      server: {
        id: record.id,
        crewId: record.crewId,
        scheduledFor: record.scheduledFor,
        revision: record.revision,
      },
    };
  }
  const changes = edit.changes || {};
  const updated = {
    id: record.id,
    crewId: record.crewId,
    scheduledFor: record.scheduledFor,
    revision: record.revision + 1,
  };
  if (Object.prototype.hasOwnProperty.call(changes, 'crewId')) {
    updated.crewId = changes.crewId;
  }
  if (Object.prototype.hasOwnProperty.call(changes, 'scheduledFor')) {
    updated.scheduledFor = changes.scheduledFor;
  }
  return { status: 'applied', record: updated };
}

